DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.admin_dashboard(text,text,integer,uuid)'::regprocedure) INTO f;f:=replace(f,'EXISTS(SELECT 1 FROM profiles WHERE is_demo)','EXISTS(SELECT 1 FROM seasons WHERE is_demo)');f:=replace(f,'''day'',d,''season''','''day'',d,''open_reports'',(SELECT count(DISTINCT post_id) FROM reports),''season''');EXECUTE f;
SELECT pg_get_functiondef('public.admin_clear_demo()'::regprocedure) INTO f;f:=replace(f,'UPDATE profiles SET demo_today=NULL','DELETE FROM admin_streak_resets WHERE is_demo; UPDATE profiles SET demo_today=NULL');EXECUTE f;
SELECT pg_get_functiondef('public.admin_seed_demo(jsonb,boolean)'::regprocedure) INTO f;f:=replace(f,'INSERT INTO announcements(title,body,is_demo)', 'INSERT INTO detox_sessions(user_id,minutes,started_at,ended_at,last_seen_at,completed,day,season_id,is_demo) SELECT ids[g],30,(sd+10)::timestamp+interval ''18 hours'',(sd+10)::timestamp+interval ''18 hours 30 minutes'',(sd+10)::timestamp+interval ''18 hours 30 minutes'',true,sd+10,sid,true FROM generate_series(1,8)g; INSERT INTO announcements(title,body,is_demo)');EXECUTE f; END $$;